	protected List<Allergy> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Allergys:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Allergy : " );        
		List<Allergy> collection  = new ArrayList<>();

		try {
			// call the static get method on the AllergyService
			collection = AllergyService.getAllergyInstance().getAllAllergy();
			assertNotNull( collection, "An Empty collection of Allergy was incorrectly returned.");
			
			// Now print out the values
			Allergy entity = null;            
			Iterator<Allergy> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getAllergyId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

